"""Market sync: pushes the market quantity of every changed product to the vendor."""
from datetime import datetime, timedelta

from hbstock.market.feed import build_feed


class SyncService:
    def __init__(self, repo, client, settings, on_synced=None, now=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.on_synced = on_synced
        self.now = now or datetime.now
        self.last_sent = {}
        self.resumed_on = {}  # sku -> market day it was last put back on sale

    def run(self, full=False):
        skus = [p.sku for p in self.repo.products()] if full else self.repo.take_dirty()
        if full:
            self.repo.take_dirty()
        products = [self.repo.product(sku) for sku in skus]
        lines, sent = build_feed(products, self.settings)
        day = self._market_day()
        # nothing to tell the market about a product whose announced quantity did not move
        changed = [line for line, sku in zip(lines, sent) if full or self.last_sent.get(sku) != sent[sku]]
        # putting a product back on sale makes the market send restock alerts; more than one
        # per market day is a policy warning, so a second time waits for the next full sync
        changed = [line for line in changed if not self._second_resume(line.split("\t", 1)[0], sent, day)]
        if not changed:
            return {"transfer": None, "lines": 0, "skus": []}
        transfer = self.client.push(changed)
        pushed = [line.split("\t", 1)[0] for line in changed]
        for sku in pushed:
            if self._is_resume(sku, sent):
                self.resumed_on[sku] = day
            self.last_sent[sku] = sent[sku]
        if self.on_synced:
            self.on_synced()
        return {"transfer": transfer.transfer_id, "lines": transfer.lines, "skus": pushed}

    def _market_day(self):
        # the marketplace's sales day runs from 06:00 to 06:00
        return (self.now() - timedelta(hours=self.settings.market_day_start_hour)).date()

    def _is_resume(self, sku, sent):
        return self.last_sent.get(sku) == 0 and sent[sku] > 0

    def _second_resume(self, sku, sent, day):
        return self._is_resume(sku, sent) and self.resumed_on.get(sku) == day

